# THE SOUND MIX (VID-27): a fixed script shipped with the serve and run by the `sound` tool step (entry `mix`) with the person's sound runtime
# (python with numpy, piper-tts and faster-whisper; see scripts/install-sound-runtime.sh). Every step is code except the tiny voice and the tiny speech-to-text check.
# usage: python team_sound_mix.py job.json   -> prints the last line `@sound-report {json}`; exit 1 when a check fails.
# job: {video, out, cues:[{id,t}], text, voice, spec:{beats:{id:{sfx,gain_db,visual}}, narration:{start_s,end_s,wps,gain_db}, music:{gain_db,duck_db}, target_lufs, true_peak_max}}
import json, os, re, subprocess, sys, time, wave
import numpy as np
SR = 44100; FPS = 30
SOFT = {"whoosh", "outwhoosh", "swish"}   # a soft sound has no sharp onset: its tolerance is wider than one frame
def write_wav(path, x):
    x = np.clip(x, -1, 1)
    with wave.open(path, "wb") as w: w.setnchannels(1); w.setsampwidth(2); w.setframerate(SR); w.writeframes((x * 32767).astype(np.int16).tobytes())
def read_wav(path):
    out = subprocess.run(["ffmpeg", "-v", "error", "-i", path, "-f", "f32le", "-ac", "1", "-ar", str(SR), "-"], capture_output=True, check=True).stdout; return np.frombuffer(out, dtype=np.float32)
def env(x, win=0.005):
    n = max(1, int(SR * win)); return np.sqrt(np.convolve(x * x, np.ones(n) / n, mode="same"))
# ---- THE KIT (VID-29): generated by code, so there is no library and no licence to carry; a manifest says what each asset is, so a licensed pack in the same format can replace it.
KIT_LICENSE = "generated by team_sound_mix.py (code); CC0, no third-party material"
EFFECTS = {  # id: description the leader's `want` is matched against
 "pop": "a short cheerful pop, a bubble, something appears", "ping": "a small bright bell ping, a label or a note", "thump": "a strong confident low hit, an impact, something heavy lands", "whoosh": "a fast soft whoosh, camera zoom, air moving in",
 "swish": "a light swish, a line slides in, a quick wipe", "outwhoosh": "a whoosh that fades away, a scene leaves, an ending", "click": "a tiny dry click, a button, a tick", "chime": "a gentle warm chime, something holy or magical",
 "sparkle": "a rising sparkle, magic, wonder, a reveal", "splash": "a water splash, the sea, a wave, rain", "rumble": "a deep rumble, an earthquake, thunder, danger", "horn": "a brass horn call, a trumpet, a fanfare, victory",
 "boing": "a springy cartoon boing, a bounce, a funny movement", "drum_hit": "a single drum beat, a kick, a march", "snare": "a snare hit, a short sharp crack, a battle", "page_flip": "a paper page turning, a book, a scroll unrolling",
 "wind": "a slow wind, a desert, empty space, loneliness", "sting_low": "a dark low sting, a threat, a plague, tension"}
BEDS = {"triumphant": "triumphant, victorious, heroic, brave, a battle won, a great deliverance", "mysterious": "mysterious, ancient, dramatic, awe, a miracle, divine, a vision", "gentle": "gentle, peaceful, calm, quiet, pastoral, tender, prayer",
        "tense": "tense, dangerous, threatening, a trial, peril, a test of faith", "joyful": "joyful, playful, bright, celebration, new life, a garden, a happy beginning"}
def _norm(x, peak=0.9): return (x / np.abs(x).max() * peak).astype(np.float32)
def build_effects():
    t = lambda d: np.arange(int(SR * d)) / SR; rng = np.random.default_rng(7); K = {}
    def band(d, lo, hi, a_in, a_out):
        n = int(SR * d); sp = np.fft.rfft(rng.standard_normal(n)); f = np.fft.rfftfreq(n, 1 / SR); sp[(f < lo) | (f > hi)] = 0; y = np.fft.irfft(sp, n); y /= np.abs(y).max()
        x = np.arange(n) / SR; return y * np.minimum(1, x / a_in) * np.minimum(1, (d - x) / a_out)
    x = t(0.25); K["pop"] = np.sin(2 * np.pi * (500 + 2200 * x) * x) * np.exp(-14 * x)
    x = t(0.6); K["ping"] = (np.sin(2 * np.pi * 1320 * x) * np.exp(-6 * x) + 0.4 * np.sin(2 * np.pi * 2640 * x) * np.exp(-9 * x)) * 0.8
    x = t(0.5); K["thump"] = np.sin(2 * np.pi * (60 + 90 * np.exp(-35 * x)) * x) * np.exp(-7 * x) + 0.25 * np.sin(2 * np.pi * 220 * x) * np.exp(-30 * x)
    K["whoosh"] = band(0.7, 300, 3500, 0.25, 0.4) * 0.7; K["swish"] = band(0.4, 2500, 7000, 0.1, 0.25) * 0.5; K["outwhoosh"] = K["whoosh"][::-1].copy()
    x = t(0.12); K["click"] = rng.standard_normal(len(x)) * np.exp(-400 * x) * 0.6 + np.sin(2 * np.pi * 2000 * x) * np.exp(-300 * x)
    x = t(0.9); K["chime"] = sum(a * np.sin(2 * np.pi * f * x) for f, a in ((880, 1), (1320, 0.6), (1760, 0.4))) * np.exp(-4 * x)
    x = t(0.9); sp = np.zeros_like(x)
    for k, f in enumerate((1200, 1500, 1800, 2200, 2640)): y = np.zeros_like(x); s0 = int(k * 0.06 * SR); tt = np.arange(len(x) - s0) / SR; y[s0:] = np.sin(2 * np.pi * f * tt) * np.exp(-9 * tt); sp += y
    K["sparkle"] = sp
    x = t(0.7); K["splash"] = band(0.7, 600, 6000, 0.01, 0.6) * np.exp(-5 * x)
    K["rumble"] = band(1.2, 30, 140, 0.4, 0.6)
    x = t(0.6); K["horn"] = sum(np.sin(2 * np.pi * 220 * k * x * (1 + 0.004 * np.sin(2 * np.pi * 5.5 * x))) / k for k in range(1, 7)) * np.minimum(1, x / 0.06) * np.exp(-2.2 * x)
    x = t(0.6); K["boing"] = np.sin(2 * np.pi * (300 + 200 * np.sin(2 * np.pi * 9 * x) * np.exp(-3 * x)) * x) * np.exp(-4 * x)
    x = t(0.5); K["drum_hit"] = np.sin(2 * np.pi * (50 + 120 * np.exp(-40 * x)) * x) * np.exp(-9 * x) + 0.3 * rng.standard_normal(len(x)) * np.exp(-120 * x)
    x = t(0.3); K["snare"] = band(0.3, 1000, 8000, 0.002, 0.25) * np.exp(-18 * x) + 0.5 * np.sin(2 * np.pi * 180 * x) * np.exp(-25 * x)
    K["page_flip"] = np.concatenate([band(0.1, 3000, 9000, 0.01, 0.08), np.zeros(int(SR * 0.04)), band(0.12, 3000, 9000, 0.01, 0.1) * 0.7])
    K["wind"] = band(1.6, 200, 1500, 0.7, 0.8) * 0.8
    x = t(1.2); K["sting_low"] = (np.sin(2 * np.pi * 55 * x) + 0.7 * np.sin(2 * np.pi * 82 * x)) * np.minimum(1, x / 0.5) * np.exp(-1.6 * x)
    return {k: _norm(v) for k, v in K.items()}
def build_beds():
    n = int(SR * 8.0); rng = np.random.default_rng(11); out = {}
    def note(buf, t0, f, d, amp, kind="pluck"):
        s0 = int(t0 * SR); m = int(d * SR); tt = np.arange(m) / SR
        v = {"pluck": np.sin(2 * np.pi * f * tt) * np.exp(-5 * tt), "saw": sum(np.sin(2 * np.pi * f * k * tt) / k for k in range(1, 6)) * np.exp(-3 * tt), "pad": np.sin(2 * np.pi * f * tt) * np.minimum(1, tt / 0.8) * np.minimum(1, (d - tt) / 0.8)}[kind]
        e = min(len(buf), s0 + m); buf[s0:e] += (v * amp)[: e - s0]
    B = np.zeros(n, np.float32)
    for bar, (root, tones) in enumerate([(130.8, (261.6, 329.6, 392.0)), (98.0, (196.0, 246.9, 293.7)), (110.0, (220.0, 261.6, 329.6)), (87.3, (174.6, 220.0, 261.6))]):
        for k in range(4): note(B, bar * 2 + k * 0.5, root, 0.45, 0.5, "saw")
        for k in range(8): note(B, bar * 2 + k * 0.25, tones[k % 3] * (2 if k % 4 == 3 else 1), 0.3, 0.35)
    out["triumphant"] = B
    B = np.zeros(n, np.float32)
    for f in (110.0, 164.8, 220.0, 261.6): note(B, 0, f, 8.0, 0.35, "pad")
    for k in range(4): note(B, 1.0 + k * 2, 880.0 * (1.5 if k % 2 else 1), 1.0, 0.25)
    out["mysterious"] = B * (0.8 + 0.2 * np.sin(2 * np.pi * 0.5 * np.arange(n) / SR))
    B = np.zeros(n, np.float32)
    for k, f in enumerate([261.6, 293.7, 329.6, 392.0, 440.0]): pass
    for k in range(16): note(B, k * 0.5, [261.6, 329.6, 392.0, 440.0, 392.0, 329.6][int(rng.integers(0, 6))], 0.9, 0.4)
    out["gentle"] = B
    B = np.zeros(n, np.float32)
    for k in range(32): note(B, k * 0.25, 82.4, 0.2, 0.8, "pluck")
    note(B, 0, 164.8, 8.0, 0.18, "pad"); note(B, 0, 174.6, 8.0, 0.18, "pad")
    out["tense"] = B
    B = np.zeros(n, np.float32)
    for k in range(32): note(B, k * 0.25, [392.0, 493.9, 587.3, 784.0][k % 4], 0.18, 0.4)
    for k in range(8): note(B, k, 196.0, 0.4, 0.5, "saw")
    out["joyful"] = B
    return {k: _norm(v, 0.8) for k, v in out.items()}
def kit_dir_ready(d):
    m = os.path.join(d, "manifest.json")
    if os.path.exists(m): return json.load(open(m))
    os.makedirs(d, exist_ok=True); man = {"license": KIT_LICENSE, "effects": [], "music": []}
    for k, v in build_effects().items(): write_wav(os.path.join(d, f"{k}.wav"), v); man["effects"].append({"id": k, "file": f"{k}.wav", "desc": EFFECTS[k], "duration_s": round(len(v) / SR, 2), "attack_s": round(attack_s(v), 3), "license": KIT_LICENSE})
    for k, v in build_beds().items(): write_wav(os.path.join(d, f"bed_{k}.wav"), v); man["music"].append({"id": k, "file": f"bed_{k}.wav", "desc": BEDS[k], "duration_s": round(len(v) / SR, 2), "license": KIT_LICENSE})
    json.dump(man, open(m, "w"), indent=1); return man
_EMB = {}
def embed(texts, model, base):
    """Embeddings by Ollama, remembered by text: one call fetches every text not seen yet."""
    import urllib.request
    miss = [t for t in dict.fromkeys(texts) if (model, t) not in _EMB]
    if miss:
        r = urllib.request.urlopen(urllib.request.Request(base.rstrip("/") + "/api/embed", json.dumps({"model": model, "input": miss}).encode(), {"content-type": "application/json"}), timeout=60)
        for t, v in zip(miss, json.load(r)["embeddings"]): _EMB[(model, t)] = v
    return [_EMB[(model, t)] for t in texts]
def pick(query, items, model, base):
    """The asset whose description is closest to the wanted one (cosine over embeddings) -> (id, score, runner-up id)."""
    v = embed([query] + [i["desc"] for i in items], model, base); q = np.array(v[0]); sc = []
    for it, e in zip(items, v[1:]): e = np.array(e); sc.append((float(q @ e / (np.linalg.norm(q) * np.linalg.norm(e))), it["id"]))
    sc.sort(reverse=True); return sc[0][1], round(sc[0][0], 3), (sc[1][1] if len(sc) > 1 else None)
def attack_s(x):
    e = env(x, 0.004); return float(np.argmax(e >= 0.3 * e.max()) / SR)
def motion(video):
    raw = subprocess.run(["ffmpeg", "-v", "error", "-i", video, "-vf", f"fps={FPS},scale=96:54,format=gray", "-f", "rawvideo", "-"], capture_output=True, check=True).stdout
    fr = np.frombuffer(raw, dtype=np.uint8).reshape(-1, 54, 96).astype(np.float32); return np.abs(np.diff(fr, axis=0)).mean(axis=(1, 2))
def lufs(path):
    r = subprocess.run(["ffmpeg", "-v", "info", "-i", path, "-af", "ebur128=peak=true", "-f", "null", "-"], capture_output=True, text=True).stderr
    i = re.findall(r"I:\s+(-?[0-9.]+) LUFS", r); p = re.findall(r"Peak:\s+(-?[0-9.]+) dBFS", r); return (float(i[-1]) if i else None, float(p[-1]) if p else None)
def fit_script(text, win_s, wps):
    budget = max(1, int(win_s * wps)); words = text.replace(".", "").split()[:budget]; return " ".join(words).rstrip(",;:") + ".", budget
def check_speech(ref_text, heard):
    """The round trip, for a tiny recogniser: it must catch garbage, silence or an overrun, not grade names. Recall over ALL words with a fuzzy match (>= 0.75: three of four heard); a capitalised word it misses is a warning."""
    import difflib
    hw = re.sub(r"[^a-z0-9' ]", "", heard.lower()).split(); words = [re.sub(r"[^a-z0-9']", "", w.lower()) for w in ref_text.replace(".", "").split()]; words = [w for w in words if w]
    got = [w for w in words if w in hw or difflib.get_close_matches(w, hw, n=1, cutoff=0.7)]; recall = len(got) / max(1, len(words))
    names = [re.sub(r"[^a-z0-9']", "", w.lower()) for i, w in enumerate(ref_text.replace(".", "").split()) if w[:1].isupper() and i > 0]
    warn = [p for p in names if p and not difflib.get_close_matches(p, hw, n=1, cutoff=0.5)]
    return recall, warn
def main(job):
    spec = job["spec"]; out_wav = os.path.splitext(job["out"])[0]; work = os.path.dirname(os.path.abspath(job["out"])) or "."; T = {}
    def lap(n, t0): T[n] = round(time.time() - t0, 3)
    cues = sorted(job["cues"], key=lambda c: c["t"]); t0 = time.time(); kdir = job.get("kit_dir") or os.path.join(work, "kit"); man = kit_dir_ready(kdir)
    eff = {e["id"]: e for e in man["effects"]}; K = {k: read_wav(os.path.join(kdir, e["file"])) for k, e in eff.items()}; att = {k: attack_s(v) for k, v in K.items()}; lap("sfx kit", t0)
    emb = job.get("embed_model", "nomic-embed-text"); base = job.get("embed_url", "http://127.0.0.1:11434"); chosen = {"effects": {}, "music": None}
    n = int(SR * float(job.get("duration_s", 5.0))); sfx = np.zeros(n, np.float32); rep = {"cues": [], "kit_license": man.get("license")}
    t0 = time.time(); wants = [b["want"] for b in spec["beats"].values() if b.get("want")]
    if wants: embed(wants + [e["desc"] for e in eff.values()] + [b["desc"] for b in man["music"]], emb, base)
    for c in cues:
        b = spec["beats"].get(c["id"])
        if not b: rep["cues"].append({"id": c["id"], "skipped": "no sound for this beat in the spec"}); continue
        how = "named"; score = None
        if b.get("want"): sid, score, runner = pick(b["want"], list(eff.values()), emb, base); how = f"matched (score {score}, next {runner})"
        else: sid = b["sfx"]
        if sid not in K: rep["cues"].append({"id": c["id"], "skipped": f"the kit has no sound `{sid}`"}); continue
        a = att[sid]; start = max(0.0, c["t"] - a); x = K[sid] * 10 ** (b["gain_db"] / 20); s = int(start * SR); e = min(n, s + len(x)); sfx[s:e] += x[: e - s]; chosen["effects"][c["id"]] = sid
        rep["cues"].append({"id": c["id"], "t": c["t"], "sfx": sid, "chosen": how, "visual": b.get("visual", "static"), "attack_s": round(a, 3), "start_s": round(start, 3)})
    lap("choose and place effects", t0)
    nar = spec["narration"]; win = nar["end_s"] - nar["start_s"]; text, budget = fit_script(job["text"], win, nar["wps"]); rep["script"] = text
    from piper import PiperVoice
    t0 = time.time(); voice = PiperVoice.load(job["voice"]); wp = os.path.join(work, "narration.wav")
    # FIT BY TRIMMING (found in the channel prototype: eight long words overran the window and the whole shot failed): drop trailing words and speak again (half a second a pass) until it fits, never below three words
    words = text.rstrip(".").split(); cut = 0
    while True:
        with wave.open(wp, "wb") as w: voice.synthesize_wav(" ".join(words).rstrip(",;:- ") + ".", w)
        x = read_wav(wp); dur = len(x) / SR
        if dur <= win * 1.08 or len(words) <= 3: break
        words = words[:-1]; cut += 1
    if cut: text = " ".join(words).rstrip(",;:- ") + "."; rep["script"] = text; rep["trimmed_words"] = cut
    lap("tts", t0); rep["narration_s"] = round(dur, 2)
    if dur > win:
        f = min(dur / win, 1.08); x = np.frombuffer(subprocess.run(["ffmpeg", "-v", "error", "-i", wp, "-af", f"atempo={f:.4f}", "-ar", str(SR), "-f", "f32le", "-ac", "1", "-"], capture_output=True, check=True).stdout, dtype=np.float32); dur = len(x) / SR; rep["atempo"] = round(f, 3)
    narr = np.zeros(n, np.float32); s = int(nar["start_s"] * SR); e = min(n, s + len(x)); narr[s:e] = x[: e - s]; rep["narration_end_s"] = round(nar["start_s"] + dur, 2)
    mus_spec = spec["music"]; beds = {b["id"]: b for b in man["music"]}; t0 = time.time()
    if mus_spec.get("bed"): bed_id, why = mus_spec["bed"], "named"
    else:
        q = mus_spec.get("want") or ""; q = (q + " " + (job.get("music_text") or "")).strip(); bed_id, sc, runner = pick(q, list(beds.values()), emb, base); why = f"matched to \"{q[:80]}\" (score {sc}, next {runner})"
    bed = read_wav(os.path.join(kdir, beds[bed_id]["file"])); mus = np.tile(bed, int(np.ceil(n / len(bed))))[:n].astype(np.float32); fade = int(0.4 * SR); mus[-fade:] *= np.linspace(1, 0, fade); chosen["music"] = bed_id; rep["music"] = {"bed": bed_id, "chosen": why}; lap("choose music", t0)
    e_n = np.convolve(np.abs(narr), np.ones(int(SR * 0.05)) / int(SR * 0.05), mode="same"); duck = np.where(e_n > 0.01, 10 ** (spec["music"]["duck_db"] / 20), 1.0); duck = np.convolve(duck, np.ones(int(SR * 0.12)) / int(SR * 0.12), mode="same")
    raw = sfx + narr * 10 ** (nar["gain_db"] / 20) * 0.9 + mus * duck * 10 ** (spec["music"]["gain_db"] / 20); write_wav(out_wav + ".raw.wav", raw / max(1.0, np.abs(raw).max()))
    t0 = time.time(); subprocess.run(["ffmpeg", "-v", "error", "-y", "-i", out_wav + ".raw.wav", "-af", f"loudnorm=I={spec['target_lufs']}:TP=-1.5:LRA=11", "-ar", str(SR), out_wav + ".norm.wav"], check=True)
    i1, _p1 = lufs(out_wav + ".norm.wav"); g = (spec["target_lufs"] - i1) if i1 is not None else 0.0   # one pass of loudnorm can miss a short clip: measure and correct, then limit the peak
    subprocess.run(["ffmpeg", "-v", "error", "-y", "-i", out_wav + ".norm.wav", "-af", f"volume={g:.2f}dB,alimiter=limit=0.84:level=disabled", "-ar", str(SR), out_wav + ".mix.wav"], check=True)
    subprocess.run(["ffmpeg", "-v", "error", "-y", "-i", job["video"], "-i", out_wav + ".mix.wav", "-c:v", "copy", "-c:a", "aac", "-b:a", "160k", "-shortest", job["out"]], check=True); lap("mix and mux", t0)
    checks = []; ck = lambda name, ok, detail: checks.append({"check": name, "ok": bool(ok), "detail": detail})
    t0 = time.time(); I, P = lufs(out_wav + ".mix.wav")
    ck("loudness within 1.5 LU of the target", I is not None and abs(I - spec["target_lufs"]) <= 1.5, f"{I} LUFS, target {spec['target_lufs']}")
    ck("true peak under the ceiling", P is not None and P <= spec["true_peak_max"], f"{P} dBFS, ceiling {spec['true_peak_max']}")
    ck("narration fits its window", rep["narration_end_s"] <= nar["end_s"] + 0.05, f"ends {rep['narration_end_s']} s, window ends {nar['end_s']} s")
    from faster_whisper import WhisperModel
    asr = WhisperModel("tiny.en", device="cpu", compute_type="int8", cpu_threads=4)
    r16 = np.frombuffer(subprocess.run(["ffmpeg", "-v", "error", "-i", wp, "-f", "f32le", "-ac", "1", "-ar", "16000", "-"], capture_output=True, check=True).stdout, dtype=np.float32)
    segs, _ = asr.transcribe(r16, word_timestamps=True, beam_size=1); words = [w for sg in segs for w in sg.words]; heard = " ".join(w.word.strip() for w in words)
    recall, warn = check_speech(text, heard); ck("the script is heard (round trip: at least three of four words)", recall >= 0.75, f"recall {recall:.2f}; heard: {heard}" + (f"; names not recognised (warning only): {', '.join(warn)}" if warn else ""))
    rep["word_times"] = [(w.word.strip(), round(w.start + nar["start_s"], 2), round(w.end + nar["start_s"], 2)) for w in words]
    # CAPTIONS (VID-29): a sidecar .srt timed from the heard words (the on-screen subtitle already shows the same words, so they are not burned in)
    def stamp(t): ms = int(round(t * 1000)); return f"{ms // 3600000:02d}:{ms // 60000 % 60:02d}:{ms // 1000 % 60:02d},{ms % 1000:03d}"
    wt = rep["word_times"]; groups = [wt[i:i + 7] for i in range(0, len(wt), 7)]; srt = out_wav + ".srt"
    open(srt, "w").write("".join(f"{k + 1}\n{stamp(g[0][1])} --> {stamp(min(g[-1][2] + 0.1, float(job.get('duration_s', 5.0))))}\n{' '.join(x[0] for x in g)}\n\n" for k, g in enumerate(groups))); rep["captions"] = srt
    letters = lambda ws: sum(len(re.sub(r"[^a-z]", "", w.lower())) for w in ws)   # a recogniser may merge or split words ("Break Out" -> "breakout"): compare the letters covered, not the word count
    ck("captions cover the script and sit inside the clip", letters([x[0] for x in wt]) >= 0.85 * letters(text.replace(".", "").split()) and all(0 <= x[1] <= x[2] <= float(job.get("duration_s", 5.0)) + 0.1 for x in wt), f"{len(wt)} timed words ({letters([x[0] for x in wt])} letters) for {len(text.replace('.', '').split())} script words ({letters(text.replace('.', '').split())} letters)")
    lic = [k for k, e in eff.items() if k in chosen["effects"].values() and not e.get("license")]; ck("every sound used carries a licence in the manifest", not lic and all(beds[chosen["music"]].get("license") for _ in [0]), f"{len(chosen['effects'])} effects and the bed `{chosen['music']}` from the kit ({man.get('license')})")
    en_sfx = env(sfx, 0.004); mo = motion(job["video"]); base = float(np.median(mo)) + 1e-6
    for c in rep["cues"]:
        if "t" not in c: continue
        soft = c["sfx"] in SOFT; tol = 0.08 if soft else 1 / FPS + 0.004
        w0, w1 = int(max(0, c["t"] - 0.1) * SR), int((c["t"] + 0.1) * SR); seg = en_sfx[w0:w1]; pk = en_sfx[int(max(0, c["t"] - 0.3) * SR): int((c["t"] + 0.5) * SR)].max()
        onset = (w0 + int(np.argmax(seg >= 0.3 * min(seg.max(), pk)))) / SR if len(seg) and seg.max() > 0 else None; aoff = None if onset is None else round(onset - c["t"], 3)
        ok_a = aoff is not None and (abs(aoff) <= tol or c["t"] == 0); c["audio_offset_s"] = aoff
        ck(f"cue {c['id']}: the {'soft ' if soft else ''}sound lands within {tol:.3f} s of the cue", ok_a, f"{aoff} s from the cue")
        if c["visual"] == "big":   # only a big picture event is verified by pixels; small ones are verified statically by the cue sheet
            f = round(c["t"] * FPS); thr = max(3 * base, base + 1.0); found = next((k for k in range(max(0, f - 3), min(len(mo), f + 10)) if mo[k] >= thr), None)
            voff = None if found is None else round((found - f) / FPS, 3); c["visual_offset_s"] = voff; ck(f"cue {c['id']}: the big picture event is within 3 frames", voff is not None and abs(voff) <= 0.1, f"{'none found' if voff is None else str(voff) + ' s'} from the cue")
    lap("verification", t0); rep["checks"] = checks; rep["timing_s"] = T; rep["total_s"] = round(sum(T.values()), 2); rep["ok"] = all(c["ok"] for c in checks)
    print("@sound-report " + json.dumps(rep, ensure_ascii=False)); return 0 if rep["ok"] else 1
if __name__ == "__main__":
    sys.exit(main(json.load(open(sys.argv[1]))))
